import React, { useState } from 'react';
import { register, login } from '../services/api';

export default function Login({ onLogin }){
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [mode, setMode] = useState('login');
  const [err, setErr] = useState(null);

  async function submit(e){
    e.preventDefault();
    try{
      const res = mode==='login' ? await login(username,password) : await register(username,password);
      if (res.msg === 'ok'){
        onLogin(res.user || {username});
      } else { setErr(JSON.stringify(res)); }
    }catch(e){ setErr(String(e)); }
  }

  return (
    <div style={{display:'flex',justifyContent:'center',alignItems:'center',height:'100vh'}}>
      <form onSubmit={submit} style={{width:320,padding:20,border:'1px solid #ddd',borderRadius:8}}>
        <h3>{mode==='login' ? 'Login' : 'Register'}</h3>
        <input placeholder='username' value={username} onChange={e=>setUsername(e.target.value)} style={{width:'100%',padding:8,margin:'8px 0'}} />
        <input placeholder='password' type='password' value={password} onChange={e=>setPassword(e.target.value)} style={{width:'100%',padding:8,margin:'8px 0'}} />
        <button type='submit' style={{width:'100%',padding:10}}>{mode==='login' ? 'Login' : 'Register'}</button>
        <div style={{marginTop:8,textAlign:'center'}}>
          <button type='button' onClick={()=>setMode(mode==='login'?'register':'login')} style={{background:'none',border:'none',color:'#06f',cursor:'pointer'}}>{mode==='login' ? 'Create account' : 'Have account? Login'}</button>
        </div>
        {err && <div style={{color:'red',marginTop:8}}>{err}</div>}
      </form>
    </div>
  );
}
